const listQualityAcknowledgements = `-- name: ListQualityAcknowledgements :many
SELECT acknowledgement_id, tenant_id, version_id, document_id, person_id, role, acknowledged_at FROM quality.document_acknowledgement
WHERE tenant_id = $1 AND version_id = $2
ORDER BY acknowledged_at
`

type ListQualityAcknowledgementsParams struct {
	TenantID  uuid.UUID
	VersionID uuid.UUID
}

func (q *Queries) ListQualityAcknowledgements(ctx context.Context, arg ListQualityAcknowledgementsParams) ([]QualityDocumentAcknowledgement, error) {
	rows, err := q.db.Query(ctx, listQualityAcknowledgements, arg.TenantID, arg.VersionID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []QualityDocumentAcknowledgement{}
	for rows.Next() {
		var i QualityDocumentAcknowledgement
		if err := rows.Scan(
			&i.AcknowledgementID,
			&i.TenantID,
			&i.VersionID,
			&i.DocumentID,
			&i.PersonID,
			&i.Role,
			&i.AcknowledgedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

